/// Trait allowing `OpRemove` to work with both plain-vector (`i32` index) and
/// sorted/tree (`i64` packed iterator) state variables.
pub trait IterState {
    fn get_cur(&self) -> i32;
    fn set_cur(&mut self, n: i32);
    fn get_finish(&self) -> u32 {
        u32::MAX
    }
    fn set_finish(&mut self, _n: u32) {}
    /// Plain-vector iteration: the whole state is a signed i64
    /// counter (no packed finish-field semantics).  Default
    /// implementation truncates to i32 and delegates to `set_cur`,
    /// which is correct for the i32 impl.  The i64 impl overrides
    /// to write the full 64-bit value — otherwise `set_cur(-1)`
    /// would zero-extend 0xFFFFFFFF, which the generated loop then
    /// treats as 4_294_967_295 and skips past the end of the
    /// vector instead of decrementing to -1.
    fn set_cur_i64_plain(&mut self, n: i64) {
        self.set_cur(n as i32);
    }
    /// Plain-vector: read as i64 (sign-extends for i32 impl, raw for
    /// i64 impl).  Used by `OpRemove` when `on = 0`.
    fn get_cur_i64_plain(&self) -> i64 {
        i64::from(self.get_cur())
    }
}

impl IterState for i32 {
    fn get_cur(&self) -> i32 {
        *self
    }
    fn set_cur(&mut self, n: i32) {
        *self = n;
    }
}

impl IterState for i64 {
    fn get_cur(&self) -> i32 {
        ((*self as u64) as u32).cast_signed()
    }
    fn set_cur(&mut self, n: i32) {
        let finish = (*self as u64) >> 32;
        *self = ((finish << 32) | u64::from(n as u32)).cast_signed();
    }
    fn get_finish(&self) -> u32 {
        ((*self as u64) >> 32) as u32
    }
    fn set_finish(&mut self, n: u32) {
        let cur = (*self as u64) as u32;
        *self = ((u64::from(n) << 32) | u64::from(cur)).cast_signed();
    }
    fn set_cur_i64_plain(&mut self, n: i64) {
        *self = n;
    }
    fn get_cur_i64_plain(&self) -> i64 {
        *self
    }
}

/// Remove the element at the current iterator position and update the iterator
/// so the next step visits the correct successor.
///
/// - `on & 63 == 0`: plain vector — `arg` is the element type index; size is
///   looked up via `stores.get_type(arg as u16).size`.
/// - `on & 63 == 2`: sorted vector — `arg` is the element size in bytes directly.
///
/// Bytecode equivalent: `State::remove` in `src/state/io.rs`.
///
/// # Panics
/// Panics if `data.store_nr == u16::MAX` (coroutine `DbRef`) — the compiler is
/// expected to reject `e#remove` on generator iterators before this is reached.
pub fn OpRemove<S: IterState>(
    cell: &std::cell::UnsafeCell<Stores>,
    state: &mut S,
    data: DbRef,
    on: i32,
    arg: i32,
) {
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    // Defense-in-depth: coroutine DbRefs (store_nr == u16::MAX) must not reach remove().
    // The compiler already rejects e#remove on generator iterators (CO1.5c / S24).
    assert!(
        data.store_nr != u16::MAX,
        "e#remove on coroutine DbRef — compiler check should have rejected this"
    );
    if data.store_nr == u16::MAX {
        return;
    }
    let cur = state.get_cur();
    let reverse = (on & 64) != 0;
    match on & 63 {
        0 => {
            // plain vector: arg is the element type index.
            // Use the i64-plain accessors so the generated code, which
            // drives `var_INDEX` as a raw i64 counter (`var += 1`),
            // sees a properly sign-extended value after `set_cur(-1)`.
            let elem_size = u32::from(stores.size(arg as u16));
            let cur_i64 = state.get_cur_i64_plain();
            let n = if reverse { cur_i64 + 1 } else { cur_i64 - 1 };
            vector::remove_vector(&data, elem_size, cur_i64, &mut stores.allocations);
            state.set_cur_i64_plain(n);
        }
        1 => {
            // index (red-black tree): arg is the type index; fields offset derived from it
            let cur_u = cur as u32;
            if cur_u == u32::MAX {
                return;
            }
            let tp = arg as u16;
            let fields = stores.fields(tp);
            let cur_ref = iter_ref(&data, cur_u, fields);
            // Compute successor BEFORE removing so tree pointers are still intact.
            let n_after = {
                let store = crate::keys::store(&data, &stores.allocations);
                if reverse {
                    tree::previous(store, &cur_ref)
                } else {
                    tree::next(store, &cur_ref)
                }
            };
            stores.remove(&data, &cur_ref, tp);
            if n_after == 0 {
                // Removed the last element: signal end-of-iteration.
                state.set_finish(u32::MAX);
            } else {
                // Set cur to predecessor of n_after so the next OpStep visits n_after.
                let pred = {
                    let store = crate::keys::store(&data, &stores.allocations);
                    if reverse {
                        tree::next(store, &iter_ref(&data, n_after, fields))
                    } else {
                        tree::previous(store, &iter_ref(&data, n_after, fields))
                    }
                };
                state.set_cur(pred.cast_signed());
                // If n_after equals the finish boundary, signal end-of-iteration.
                if n_after == state.get_finish() {
                    state.set_finish(u32::MAX);
                }
            }
        }
        2 => {
            // sorted vector: arg is the element size in bytes
            if cur < 0 {
                return;
            }
            let n = if reverse { cur + 1 } else { cur - 1 };
            vector::remove_vector(&data, arg as u32, i64::from(cur), &mut stores.allocations);
            state.set_cur(n);
        }
        _ => {}
    }
}

/// Remove a record from a hash or index collection.
///
/// Bytecode equivalent: `State::hash_remove` in `src/state/io.rs`.
pub fn OpHashRemove(cell: &std::cell::UnsafeCell<Stores>, data: DbRef, rec: DbRef, tp: i32) {
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    if rec.rec != 0 {
        stores.remove(&data, &rec, tp as u16);
    }
}

/// Append `count - 1` copies of the last element of `data`, expanding the vector.
///
/// Bytecode equivalent: `State::append_copy` in `src/state/io.rs`.
pub fn OpAppendCopy(cell: &std::cell::UnsafeCell<Stores>, data: DbRef, count: i64, tp: i32) {
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    let ctp = stores.content(tp as u16);
    let size = u32::from(stores.size(ctp));
    let length = vector::length_vector(&data, &stores.allocations);
    // Read v_rec before resize; from points to the last existing element.
    let v_rec_before =
        crate::keys::store(&data, &stores.allocations).get_u32_raw(data.rec, data.pos);
    let from = DbRef {
        store_nr: data.store_nr,
        rec: v_rec_before,
        pos: 8 + (length * size - size),
    };
    let multiply = count as u32;
    // Resize to accommodate `multiply` additional elements.
    vector::vector_append(&data, size, &mut stores.allocations);
    stores.vector_set_size(&data, multiply, size);
    // Re-read v_rec in case the resize moved the record.
    let v_rec = crate::keys::store(&data, &stores.allocations).get_u32_raw(data.rec, data.pos);
    for i in 0..(multiply - 1) {
        let to = DbRef {
            store_nr: data.store_nr,
            rec: v_rec,
            pos: 8 + (length + i) * size,
        };
        stores.copy_block(&from, &to, size);
        stores.copy_claims(&data, &to, ctp);
    }
}

// @PLAN12 phase 3.5a (2026-05-24) — cr_rand_seed / cr_rand_int /
// the `external::` module that wrapped them all removed.  random's
// drain to lib/random/native/ + the loft::native_call codegen
// helpers mean the cdylib is the single source of RNG state for
// both backends.  Nothing else in the loft crate referenced these
// helpers (greps were empty), so they're safe to delete.

/// Parse a `LOFT_FAKE_*` env var into an `i64`.  See the same-named
/// helper in `src/native.rs` for the full contract; duplicated here so
/// `--native`-compiled binaries honour the override the same way the
/// interpreter does.
#[cfg(not(target_arch = "wasm32"))]
fn fake_clock_env(var: &str) -> Option<i64> {
    std::env::var(var).ok()?.parse::<i64>().ok()
}

/// Return milliseconds since the Unix epoch (1970-01-01T00:00:00 UTC).
/// Returns `i64::MIN` (null) if the system clock reports a time before the epoch.
/// Honours `LOFT_FAKE_NOW_MS` when set (deterministic snapshot tests).
/// Bytecode equivalent: `n_now` in `src/native.rs`.
///
/// Plan 09 phase 01 step 1.5: migrated to the no-stores ABI
/// (`Abi::None`).  Body doesn't touch `Stores` — wall-clock read only.
#[cfg(not(target_arch = "wasm32"))]
pub fn n_now() -> i64 {
    if let Some(fake) = fake_clock_env("LOFT_FAKE_NOW_MS") {
        return fake;
    }
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map_or(i64::MIN, |d| d.as_millis() as i64)
}

/// Bytecode equivalent: `n_now` in `src/native.rs`.
#[cfg(all(target_arch = "wasm32", feature = "wasm"))]
pub fn n_now() -> i64 {
    crate::wasm::host_time_now()
}

/// Fallback for the `--html` build (wasm32, no `wasm` feature):
/// returns 0 because no host time bridge exists.  Mirror of the
/// `n_ticks` fallback below for the same target.
#[cfg(all(target_arch = "wasm32", not(feature = "wasm")))]
pub fn n_now() -> i64 {
    0
}

/// Return microseconds elapsed since program start (monotonic clock).
/// Use for frame timing and benchmarks; unaffected by wall-clock adjustments.
/// Honours `LOFT_FAKE_TICKS_US` when set (deterministic snapshot tests).
/// Bytecode equivalent: `n_ticks` in `src/native.rs`.
#[cfg(not(target_arch = "wasm32"))]
pub fn n_ticks(cell: &std::cell::UnsafeCell<Stores>) -> i64 {
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    if let Some(fake) = fake_clock_env("LOFT_FAKE_TICKS_US") {
        return fake;
    }
    stores.start_time.elapsed().as_micros() as i64
}

/// Bytecode equivalent: `n_ticks` in `src/native.rs`.  Gated on
/// target_arch, not the `wasm` feature — the `--html` build (wasm32,
/// no `wasm` feature) returns 0 because no host time bridge exists.
#[cfg(all(target_arch = "wasm32", feature = "wasm"))]
pub fn n_ticks(cell: &std::cell::UnsafeCell<Stores>) -> i64 {
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    (crate::wasm::host_time_ticks() - stores.start_time_ms) * 1000
}

#[cfg(all(target_arch = "wasm32", not(feature = "wasm")))]
pub fn n_ticks(_cell: &std::cell::UnsafeCell<Stores>) -> i64 {
    0
}

/// Return the platform path separator as a loft character (`i32`).
/// Returns `'/'` (47) on Unix and `'\\'` (92) on Windows.
/// Bytecode equivalent: `n_path_sep` in `src/native.rs`.
/// Plan 09 phase 01 step 1.5: migrated to the no-stores ABI — body
/// returns a compile-time platform constant, never touches `Stores`.
pub fn n_path_sep() -> i32 {
    crate::platform::sep() as i32
}

/// C60 piece 3: build a scratch u32-rec-nr vector from a hash,
/// ascending by the hash's key.  The parser-desugared `for e in h`
/// path calls this with the hash's type id as a compile-time constant
/// and iterates the result via Ordered (on=3).  Bytecode equivalent:
/// `n_hash_sorted` in `src/native.rs`.
pub fn n_hash_sorted(cell: &std::cell::UnsafeCell<Stores>, h: DbRef, tp: i64) -> DbRef {
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    stores.build_hash_sorted_vec(&h, tp as u16)
}

/// Raw bucket-walk sibling of `n_hash_sorted` for `for e in h par(...)` —
/// skips the key sort because the parallel queue has no use for hash order.
/// Bytecode equivalent: `n_hash_unsorted` in `src/native.rs`.
pub fn n_hash_unsorted(cell: &std::cell::UnsafeCell<Stores>, h: DbRef, tp: i64) -> DbRef {
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    stores.build_hash_unsorted_vec(&h, tp as u16)
}

/// Read the text element a par worker's `&str` parameter expects out of the
/// input row `elm` (a `vector<text>` element holds a 4-byte text-pointer at
/// `elm.pos`).  Returns an owned `String` so the borrow outlives the worker
/// call regardless of later store mutation — the per-row cost is negligible
/// next to the worker.  Emitted by `tuple_arg_prep` for text-input par workers;
/// without it the closure passes the raw `DbRef` where the worker wants `&str`.
#[must_use]
pub fn par_read_text_input(cell: &std::cell::UnsafeCell<Stores>, elm: DbRef) -> String {
    let stores: &Stores = unsafe { &*cell.get() };
    let store = &stores.allocations[elm.store_nr as usize];
    let base = store.base_ptr();
    let text_rec = unsafe {
        base.offset(elm.rec as isize * 8 + elm.pos as isize)
            .cast::<u32>()
            .read_unaligned()
    };
    store.get_str(text_rec).to_string()
}

/// P268 — JSON parser native runtime stub.  Wraps the shared
/// `crate::native::json_parse_into_stores` helper (extracted from the
/// interp `n_json_parse` body) so `--native`-compiled programs can
/// call `json_parse(text) -> JsonValue` instead of hitting the
/// per-package `todo!()` stub.  Returns a `DbRef` to the freshly
/// allocated JsonValue tree; updates `stores.last_json_errors` on
/// parse failure (read by `json_errors()` / `n_json_errors`).
/// Bytecode equivalent: `n_json_parse` in `src/native.rs`.
pub fn n_json_parse(cell: &std::cell::UnsafeCell<Stores>, raw: &str) -> DbRef {
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    crate::native::json_parse_into_stores(stores, raw)
}

/// P268 — JsonValue.field(name) native wrapper.  JObject linear-scan
/// indexer; returns the value's DbRef, or the shared JNull sentinel
/// for a missing key / non-JObject receiver.  Mirrors the interp
/// `n_field` body in `src/native.rs`.
#[allow(clippy::missing_panics_doc)] // try_from is on a non-negative loop counter
pub fn t_9JsonValue_field(
    cell: &std::cell::UnsafeCell<Stores>,
    self_ref: DbRef,
    name: &str,
) -> DbRef {
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    let discr = stores
        .store(&self_ref)
        .get_byte(self_ref.rec, self_ref.pos, 0);
    if discr != crate::native::JV_DISCR_OBJECT {
        return crate::native::jv_null_sentinel(stores);
    }
    let obj_tp = stores.name("JObject");
    let fields_pos = u32::from(stores.position(obj_tp, "fields")) + self_ref.pos;
    let fields_rec = stores
        .store(&self_ref)
        .get_i32_raw(self_ref.rec, fields_pos);
    if fields_rec <= 0 {
        return crate::native::jv_null_sentinel(stores);
    }
    let length = i64::from(stores.store(&self_ref).get_u32_raw(fields_rec as u32, 4));
    let jf_tp = stores.name("JsonField");
    let jf_size = u32::from(stores.size(jf_tp));
    let name_field_pos = u32::from(stores.position(jf_tp, "name"));
    let value_field_pos = u32::from(stores.position(jf_tp, "value"));
    for i in 0..length {
        let elm_offset = 8u32 + u32::try_from(i).expect("non-negative length") * jf_size;
        let name_rec = stores
            .store(&self_ref)
            .get_u32_raw(fields_rec as u32, elm_offset + name_field_pos);
        let stored_name = stores.store(&self_ref).get_str(name_rec).to_owned();
        if stored_name == name {
            return DbRef {
                store_nr: self_ref.store_nr,
                rec: fields_rec as u32,
                pos: elm_offset + value_field_pos,
            };
        }
    }
    crate::native::jv_null_sentinel(stores)
}

/// P268 — JsonValue.item(index) native wrapper.  JArray indexer.
/// Returns the element's DbRef or JNull sentinel.  Mirrors interp
/// `n_item`.
#[allow(clippy::missing_panics_doc)] // try_from is on a bounds-checked non-negative index
pub fn t_9JsonValue_item(
    cell: &std::cell::UnsafeCell<Stores>,
    self_ref: DbRef,
    index: i64,
) -> DbRef {
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    let index = index as i32;
    let discr = stores
        .store(&self_ref)
        .get_byte(self_ref.rec, self_ref.pos, 0);
    if discr != crate::native::JV_DISCR_ARRAY || index < 0 {
        return crate::native::jv_null_sentinel(stores);
    }
    let array_tp = stores.name("JArray");
    let items_pos = u32::from(stores.position(array_tp, "items")) + self_ref.pos;
    let items_rec = stores.store(&self_ref).get_i32_raw(self_ref.rec, items_pos);
    if items_rec <= 0 {
        return crate::native::jv_null_sentinel(stores);
    }
    let length = stores.store(&self_ref).get_u32_raw(items_rec as u32, 4) as i32;
    if index >= length {
        return crate::native::jv_null_sentinel(stores);
    }
    let jv_tp = stores.name("JsonValue");
    let jv_size = u32::from(stores.size(jv_tp));
    let elm_offset =
        8u32 + u32::try_from(index).expect("non-negative index checked above") * jv_size;
    DbRef {
        store_nr: self_ref.store_nr,
        rec: items_rec as u32,
        pos: elm_offset,
    }
}

/// P268 — JsonValue.len() native wrapper.  Length of JArray's items
/// or JObject's fields; `i64::MIN` (null) for primitive variants.
/// Mirrors interp `n_len`.
pub fn t_9JsonValue_len(cell: &std::cell::UnsafeCell<Stores>, v: DbRef) -> i64 {
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    let discr = stores.store(&v).get_byte(v.rec, v.pos, 0);
    match discr {
        x if x == crate::native::JV_DISCR_ARRAY => {
            let array_tp = stores.name("JArray");
            let items_pos = u32::from(stores.position(array_tp, "items")) + v.pos;
            let items_rec = stores.store(&v).get_i32_raw(v.rec, items_pos);
            if items_rec <= 0 {
                0
            } else {
                i64::from(stores.store(&v).get_u32_raw(items_rec as u32, 4))
            }
        }
        x if x == crate::native::JV_DISCR_OBJECT => {
            let obj_tp = stores.name("JObject");
            let fields_pos = u32::from(stores.position(obj_tp, "fields")) + v.pos;
            let fields_rec = stores.store(&v).get_i32_raw(v.rec, fields_pos);
            if fields_rec <= 0 {
                0
            } else {
                i64::from(stores.store(&v).get_u32_raw(fields_rec as u32, 4))
            }
        }
        _ => i64::MIN,
    }
}

/// P268 — JsonValue.as_text() native wrapper.  Returns the JString
/// payload, or the empty-string null sentinel for any other variant.
/// Mirrors interp `n_as_text`.
#[allow(clippy::missing_panics_doc)] // scratch.last().unwrap() — we just pushed
// @PLN10 — owned `String` (no scratch).  Null is carried as
// `STRING_NULL.to_string()` (the `"\0"` sentinel) — native text-null IS an owned
// `String` value, so `j.as_text() ?? x` / `if !j.as_text()` semantics are
// preserved.  Inline (matching name + cell ABI), so no `native_returns_owned_string`
// entry is needed (cf. `kind` / `to_json`).
pub fn t_9JsonValue_as_text(cell: &std::cell::UnsafeCell<Stores>, v: DbRef) -> String {
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    let discr = stores.store(&v).get_byte(v.rec, v.pos, 0);
    if discr == crate::native::JV_DISCR_STRING {
        let str_tp = stores.name("JString");
        let value_pos = u32::from(stores.position(str_tp, "value")) + v.pos;
        let s_rec = stores.store(&v).get_u32_raw(v.rec, value_pos);
        stores.store(&v).get_str(s_rec).to_string()
    } else {
        crate::state::STRING_NULL.to_string()
    }
}

/// P268 — JsonValue.as_long() native wrapper.  Truncates the JNumber
/// payload toward zero; returns `i64::MIN` (null) for any other
/// variant.  Mirrors interp `n_as_long`.
pub fn t_9JsonValue_as_long(cell: &std::cell::UnsafeCell<Stores>, v: DbRef) -> i64 {
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    let discr = stores.store(&v).get_byte(v.rec, v.pos, 0);
    if discr == crate::native::JV_DISCR_NUMBER {
        let num_tp = stores.name("JNumber");
        let value_pos = u32::from(stores.position(num_tp, "value")) + v.pos;
        let n = stores.store(&v).get_float(v.rec, value_pos);
        n.trunc() as i64
    } else {
        i64::MIN
    }
}

/// P268 — JsonValue.kind() native wrapper.  Returns the variant
/// name as a Str: "JNull" / "JBool" / "JNumber" / "JString" /
/// "JArray" / "JObject".
// @PLN10 — return an owned `String` instead of a `Str` borrowed from the
// never-cleared `stores.scratch`.  The native binding wraps text-var assignments
// in `(...).to_string()` and argument sites in `&*` (both work on `String` via
// `Deref<Target=str>`), so this is transparent and strictly better — the owned
// String is freed instead of leaked.
pub fn t_9JsonValue_kind(cell: &std::cell::UnsafeCell<Stores>, v: DbRef) -> String {
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    let discr = stores.store(&v).get_byte(v.rec, v.pos, 0);
    let s = match discr {
        x if x == crate::native::JV_DISCR_NULL => "JNull",
        x if x == crate::native::JV_DISCR_BOOL => "JBool",
        x if x == crate::native::JV_DISCR_NUMBER => "JNumber",
        x if x == crate::native::JV_DISCR_STRING => "JString",
        x if x == crate::native::JV_DISCR_ARRAY => "JArray",
        x if x == crate::native::JV_DISCR_OBJECT => "JObject",
        _ => "JNull",
    };
    s.to_string()
}

